//
int synopsis_probe(struct net_device *dev){

    // register functions
    dev->state = NETDEV_DOWN;
    dev->init = synopsis_init;
    dev->open = synopsis_open;
    dev->close = synopsis_close;
    dev->send_packet = synopsis_send_packet;
    dev->receive_packet = synopsis_receive_packet;
    dev->print_status = synopsis_print_status;
	dev->get_stats = synopsis_get_stats;

    return 1;
}

void flush_dcache(void)
{
	dcache_flush();
}

int synopsis_init(struct net_device *dev)
{
	synopGMACMappedAddr = (u8 *)ioremap(REG_BASE_ETH_MAC,0x04);
	synopGMAC_init_network_interface(dev);
	return 0;
}
int synopsis_open(struct net_device *dev)
{
	if(dev->state != NETDEV_UP){		
		synopsis_init(dev);
		SYNP("fun:%s>>>0x%x>>>", __func__, dev);
		
		synopGMAC_linux_close(dev);
		synopGMAC_linux_open(dev);
		synopGMAC_linux_close(dev);	//it must be close open close before open, or may be error
		synopGMAC_linux_open(dev);

		synopGMAC_resume_dma_tx(synopGMACadapter->synopGMACdev);
		synopGMAC_resume_dma_rx(synopGMACadapter->synopGMACdev);
		
		dev->state = NETDEV_UP;
	}
	return 0;
}

int synopsis_close(struct net_device *dev)
{
	/* huangjb debug: add later.uboot synop.c synopmac_halt() */

	if(dev->state != NETDEV_DOWN){
		//printf("%s called.\n",__FUNCTION__);
		synopGMAC_linux_close(dev);
//#ifdef CONFIG_CKCORE		
//		dcache_enable();
//#endif
		dev->state = NETDEV_DOWN;
	}
	return 0;
}
