int synopsis_send_packet(struct sk_buff *skb, struct net_device *dev, int async)
{
	int count = 10;
	int tx_finished = 0;

	synopGMAC_intr_handler(HANDLE_TX,(void*)dev);

	while (count > 0) {
		if (synopGMAC_linux_xmit_frames(skb, dev, async) == 0)
			break;

		count--;
		udelay(100);
	}

	if (count == 0)
		return -1;

	return 0;
}
